INSERT INTO `js_zyfw_elderly_community` VALUES (1,'111',111,'0','2025-04-09','行动不便','11','11','11'),(2,'张桂花',78,'1','1947-03-15','有慢性疾病','长期口服降压药“氨氯地平”每日一次糖尿病患者，使用“细胞素”胰岛素注射，每日三次偶有失眠，睡前服用“佐匹克隆”5mg','张奶奶性格温和，喜欢与人聊天，但因行动受限，主要通过电话或在家中窗前与路过的志愿者交流，偶尔参加社区茶话会，能流畅表达需求。','独居，子女均在外地工作，经常电话问候，社区志愿者定期探访。'),(3,'22',2,'0','2025-05-09','半自理',NULL,NULL,NULL);
