DROP TABLE IF EXISTS `sys_activity`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_activity` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '活动ID',
  `name` varchar(120) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '活动名称',
  `describe` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '活动描述',
  `location` varchar(25) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '活动地点',
  `start_time` datetime NOT NULL COMMENT '开始时间',
  `end_time` datetime NOT NULL COMMENT '结束时间',
  `organizer` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '主办方',
  `status` varchar(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '1' COMMENT '活动状态',
  `contacts` varchar(25) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '联系人',
  `contacts_phone` varchar(25) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '联系人电话',
  `substance` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '活动所需物资',
  `ask` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '志愿者要求',
  `imgs` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '活动图片',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `activity_type` varchar(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '活动类型',
  `organization_id` int NOT NULL COMMENT '志愿组织id',
  `extra` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '扩展字段',
  `number_limit` int NOT NULL COMMENT '活动人数限制',
  `attend_people_count` int DEFAULT '0' COMMENT '已参加活动人数',
  `sign_score` int DEFAULT NULL COMMENT '活动每次签到积分',
  `sign_switch` varchar(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT '0' COMMENT '活动签到开关',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=50 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='活动信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `sys_activity`
--

LOCK TABLES `sys_activity` WRITE;
/*!40000 ALTER TABLE `sys_activity` DISABLE KEYS */;
INSERT INTO `sys_activity` VALUES (39,'冬日关怀行动│温暖送到家门口','<p>亲爱的朋友们：</p><p><br></p><p>在寒冷的冬季，为帮助独居和高龄老人度过一个温暖的冬天，夕阳红关爱服务队将开展“冬日送暖上门服务”活动。本次服务任务包括：</p><p>整理冬季衣物和床品</p><p>检查热水器、取暖器等生活设备</p><p>简单打扫卫生、清洁地面和厨房</p><p><br></p>','幸福社区 5 栋','2025-05-01 00:00:00','2025-05-30 00:00:00','夕阳红关爱服务队','2','李阿姨','13812345678',NULL,'参与者需年满18岁，有责任心，能独立完成基础家务操作。每位志愿者服务至少1户老人，服务时长约2小时','/profile/upload/2025/05/05/生成志愿者助老图片_20250505230756A001.png','2025-05-03 08:45:53','2025-05-05 15:16:31','1',19,'7',10,0,NULL,'0'),(40,'健康护航日│让关爱在血压计间流淌','<p>为提升老年人健康意识，健康守护志愿团将举办“健康义诊进社区”活动，服务项目包括：</p><p>免费血压、血糖测量</p><p>健康饮食与用药知识讲解</p><p>解答老人日常健康困惑</p><p>一滴血，一份爱，守护银发健康，我们一起努力！</p>','社区服务中心一楼大厅','2025-05-01 00:00:00','2025-05-22 00:00:00','健康守护志愿团','2','王医生','13987654321',NULL,'需有医护专业背景或志愿服务经验','/profile/upload/2025/05/05/生成志愿者助老图片 (1)_20250505230813A002.png','2025-05-03 08:48:33','2025-05-03 08:48:33','2',20,'7',8,0,NULL,'0'),(41,'温情同行│陪伴老人走进春光','<p>为帮助老人增强体质、舒缓情绪，夕阳红关爱服务队将组织“暖心陪伴游公园”活动，任务内容如下：</p><p>陪老人步行、公园散步</p><p>主动交流、协助拍照留念</p><p>提供简单搀扶和防走失看护</p><p>用陪伴驱散孤独，用微笑温暖心灵！</p><p><br></p><p>每人陪同1-2位老人，活动时间约2小时。需提前到场参加简要培训。</p>','绿柳公园东门集合','2025-05-01 00:00:00','2025-05-30 00:00:00','夕阳红关爱服务队','2','陈老师','13711223344',NULL,'需身体健康、沟通能力强，具有高度责任心。','/profile/upload/2025/05/05/生成志愿者助老图片 (2)_20250505230829A003.png','2025-05-03 08:50:00','2025-05-03 08:50:00','3',19,'7',12,0,NULL,'0'),(42,'心灵港湾│与长者共度暖心时光','<p>许多老人渴望倾诉却无人倾听，为此我们组织“长者谈心会”活动，内容包括：</p><p>与老人进行一对一交流</p><p>听老人分享往事与心声</p><p>鼓励老人表达情绪、建立信任</p><p><br></p><p>欢迎心理学相关专业或有耐心、同理心的朋友参与。每位志愿者需全程参与，不中途退出，交流内容应尊重隐私，避免负面暗示。</p><p>有时候，静静聆听，就是最大的帮助。</p><p><br></p>','颐乐养老院休闲厅','2025-05-01 00:00:00','2025-05-22 00:00:00','夕阳红关爱服务队','2','张志愿','13533445566',NULL,'善于倾听，有心理学基础者优先','/profile/upload/2025/05/05/生成志愿者助老图片 (3)_20250505230848A004.png','2025-05-03 08:51:19','2025-05-03 08:51:19','4',19,'7',6,0,NULL,'0'),(43,'智能课堂│教爷爷奶奶用好手机','<p>智慧帮帮团将开展“智能手机使用培训”活动，帮助老人融入数字社会。教学内容包括：</p><p>教会老人使用微信视频通话、发送消息</p><p>指导使用健康码、扫码支付等功能</p><p>解答日常操作难题</p><p><br></p><p>志愿者需具备一定教学能力和耐心，按分组一对一教学，每节课约90分钟。需准备教学用手机和演示材料。</p><p><br></p><p>让科技不再是障碍，而成为亲情沟通的桥梁！</p>','社区党群服务中心二楼','2025-05-01 00:00:00','2025-05-22 00:00:00','智慧帮帮团','2','刘老师','18855667788',NULL,'熟悉智能手机操作，有教学经验','/profile/upload/2025/05/05/生成志愿者助老图片 (4)_20250505230901A005.png','2025-05-03 08:53:02','2025-05-03 08:53:02','5',22,'7',5,0,NULL,'0'),(44,'安全到家│为长者排查生活隐患','<p>为防止老年家庭事故发生，爱心维修志愿组将开展“居家安全检查日”活动。服务任务包括：</p><p><br></p><p>检查电线、电器、燃气安全</p><p>修理门锁、水龙头、灯泡等基础设施</p><p>协助更换电池、防滑垫等安全用品</p><p><br></p><p>志愿者需年满20岁，具备基础维修知识或接受简单技术指导。服务需穿戴统一志愿服，携带工具，自觉保护用户隐私和财产安全。</p><p><br></p><p>为老年生活筑起一道看不见的安全屏障！</p><p><br></p>','仁和里社区A区','2025-05-01 00:00:00','2025-05-29 00:00:00','爱心维修志愿组','2','孙师傅','13699887766',NULL,'具备基本电工或维修知识，年龄20-55岁','/profile/upload/2025/05/05/生成志愿者助老图片 (5)_20250505230915A006.png','2025-05-03 08:54:46','2025-05-03 08:54:46','6',24,'7',10,0,NULL,'0'),(45,'红色记忆会│与历史对话的下午茶','<p>红色记忆宣讲团将举办“红色故事分享会”，让青年与长者在记忆中共鸣。活动内容包括：</p><p><br></p><p>听老党员讲述革命经历</p><p>志愿者分享红色人物故事</p><p>组织互动提问与茶歇交流</p><p><br></p><p>鼓励有演讲表达能力或热爱红色文化的青年报名参与。活动需自备演讲稿件，提前彩排，注意文明表达与现场纪律。</p><p><br></p><p>让红色精神在社区延续，让信仰照进当下生活！</p>','社区图书室','2025-05-01 00:00:00','2025-05-30 00:00:00','红色记忆宣讲团','2','周主任','13012349876',NULL,'热爱历史、表达能力好，可熟练讲述红色故事','/profile/upload/2025/05/05/生成志愿者助老图片 (6)_20250505230929A007.png','2025-05-03 08:56:07','2025-05-03 08:56:07','8',25,'7',4,0,NULL,'0'),(46,'夕阳红关爱服务队 - 上门生活照料','<p>本活动旨在为社区内生活不能自理的老人提供上门生活照料。志愿者将为老年人提供帮助，如起床、洗漱、餐前准备、喂饭等，确保老人日常生活的基本需求得到满足</p>','绿苑社区','2025-05-01 00:00:00','2025-05-30 00:00:00','夕阳红关爱服务队','2','李建华（夕阳红关爱服务队负责人）','130-4567-8901',NULL,'志愿者需有护理经验，具备基础的生活照料技能，如帮助老人起床、洗漱、喂饭等。年龄要求：18-55岁。','/profile/upload/2025/05/05/生成志愿者助老图片 (7)_20250505230943A008.png','2025-05-03 09:29:24','2025-05-03 09:29:24','1',19,'7',3,0,NULL,'0'),(47,'暖心助餐志愿队 - 送餐到家','<p>本活动针对社区内无法外出就餐的老人，志愿者将准时为老人送去营养餐。活动不仅提供食物的配送服务，还将确保餐食的质量和老人的饮食需求。志愿者将与老人亲切交谈，确保老人生活无忧。</p>','桃花园小区','2025-05-01 00:00:00','2025-05-29 00:00:00','暖心助餐志愿队','2','张莉（暖心助餐志愿队负责人）','139-8765-4321',NULL,'志愿者需具有责任心，能准时送餐并确保食品安全。需要具备基础的沟通能力，能与老人互动。','/profile/upload/2025/05/05/生成志愿者助老图片 (8)_20250505230956A009.png','2025-05-03 09:30:43','2025-05-03 09:30:43','1',21,'7',3,0,NULL,'0'),(48,'健康守护志愿团 - 基础健康检查','<p>活动为社区内老年人提供免费的健康检查，包括血压、血糖等常规体检。志愿者将与医生协作，为参与的老人提供健康指导。通过本活动，志愿者还将普及健康知识，帮助老人更好地管理自己的健康。</p>','健康守护志愿团 - 基础健康检查','2025-05-12 00:00:00','2025-05-13 00:00:00','健康守护志愿团','2','王梅（健康守护志愿团负责人）','135-7890-1234',NULL,'志愿者需有护理或基础医疗知识，有老年人护理经验者优先。志愿者需要能够进行基本的健康检查，如血压、血糖监测等。','/profile/upload/2025/05/05/生成志愿者助老图片 (9)_20250505231007A010.png','2025-05-03 09:43:56','2025-05-03 09:43:56','2',20,'7',4,0,NULL,'0'),(49,'1111','<p>111</p>','111','2025-05-05 00:00:00','2025-05-29 00:00:00','暖心助餐志愿队','2','11111','1111',NULL,'111','/profile/upload/2025/05/05/logo_20250505232610A001.png','2025-05-05 15:26:21','2025-05-05 16:03:40','3',21,'21',11,0,NULL,'0');
