INSERT INTO `sys_comment` VALUES (32,36,5,'我现在终于可以进入评论区了','user01','2024-10-13 03:39:29','2024-10-12 19:39:28'),(33,36,5,'我现在有点事，这个活动不能参加了，我想退出','user01','2024-10-13 03:39:52','2024-10-12 19:39:51'),(34,36,5,'我又回来了','user01','2024-10-13 03:41:51','2024-10-12 19:41:50'),(35,36,5,'我现在想加入志愿者组织，之前不是志愿者，他们说无法加入','user01','2024-10-13 03:42:18','2024-10-12 19:42:17'),(36,36,19,'感觉组织志愿者管理员，是你帮我审核通过的','user01','2024-10-13 03:49:51','2024-10-12 19:49:50'),(37,36,5,'111','user01','2024-10-13 14:36:11','2024-10-13 06:36:10'),(38,36,5,'特殊的他','user01','2024-10-13 14:39:57','2024-10-13 06:39:56'),(39,38,5,'good','user03','2024-10-13 03:44:27','2024-10-12 19:44:26'),(40,39,5,'11','user11','2024-10-13 10:24:42','2024-10-13 02:24:42'),(41,36,19,'good','user01','2024-10-13 06:49:07','2024-10-12 22:49:07'),(42,44,7,'积极参与，创先创优！','123456','2024-10-13 02:21:49','2024-10-13 02:21:49'),(43,1,32,'11','admin','2025-04-26 11:58:15','2025-04-26 11:58:15'),(44,1,38,'11111','admin','2025-04-28 06:33:21','2025-04-28 06:33:21'),(45,1,38,'1111','admin','2025-04-28 06:33:24','2025-04-28 06:33:24'),(46,1,38,'1111111','admin','2025-04-28 07:42:14','2025-04-28 07:42:14'),(47,1,38,'11111111','admin','2025-05-05 08:12:05','2025-05-05 08:12:04'),(48,48,35,'qqq','11111','2025-05-05 08:44:55','2025-05-05 08:44:55');
